 "content": "def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    seeds = {}
    for r in range(h):
        for c in range(w):
            if g[r][c]:
                seeds.setdefault(g[r][c], []).append((r, c))

    for color, pts in seeds.items():
        # Each colored boundary cell sends a ray inward. A lone ray reaches
        # the opposite edge; perpendicular rays of the same color meet.
        vertical = [(r, c, 1 if r == 0 else -1) for r, c in pts if r == 0 or r == h - 1]
        horizontal = [(r, c, 1 if c == 0 else -1) for r, c in pts if c == 0 or c == w - 1]
        paired_v = set()
        paired_h = set()
        for vi, (vr, vc, vd) in enumerate(vertical):
            for hi, (hr, hc, hd) in enumerate(horizontal):
                # Their inward rays meet at (hr, vc) if neither seed lies
                # beyond the crossing in its inward direction.
                if (vd == 1 and hr >= vr or vd == -1 and hr <= vr) and (hd == 1 and vc >= hc or hd == -1 and vc <= hc):
                    for r in range(min(vr, hr), max(vr, hr) + 1):
                        g[r][vc] = color
                    for c in range(min(hc, vc), max(hc, vc) + 1):
                        g[hr][c] = color
                    paired_v.add(vi)
                    paired_h.add(hi)
        for i, (r, c, direction) in enumerate(vertical):
            if i not in paired_v:
                end = h - 1 if direction == 1 else 0
                for rr in range(min(r, end), max(r, end) + 1):
                    g[rr][c] = color
        for i, (r, c, direction) in enumerate(horizontal):
            if i not in paired_h:
                end = w - 1 if direction == 1 else 0
                for cc in range(min(c, end), max(c, end) + 1):
                    g[r][cc] = color
    return g

